INSERT INTO [dbo].[Categorias] ([Id], [Nombre], [Descripcion]) VALUES (7, N'SUV', N'Vehículo de carrocería alta, amplio y con mayor altura al suelo, generalmente de 5 a 7 plazas, buena visibilidad y espacio de carga, Cómoda, espaciosa, versátil y adecuada para terrenos irregulares, Mayor consumo de combustible, precio elevado y estacionamiento más complicado');
INSERT INTO [dbo].[Categorias] ([Id], [Nombre], [Descripcion]) VALUES (8, N'Hatchback', N'Vehículo compacto con puerta trasera que incluye el vidrio y acceso directo al maletero, generalmente de 3 a 5 puertas, Económico, fácil de estacionar y ágil en la ciudad, Maletero reducido y menor espacio interior que vehículos más grandes');
INSERT INTO [dbo].[Categorias] ([Id], [Nombre], [Descripcion]) VALUES (9, N'Sedan', N'Vehículo de carrocería de tres volúmenes con maletero separado del habitáculo, generalmente de 4 puertas y 5 plazas, Cómodo, estable en carretera y con buen espacio para pasajeros y equipaje, Menor altura al suelo, acceso al maletero limitado y menos versátil en terrenos irregulares');
INSERT INTO [dbo].[Categorias] ([Id], [Nombre], [Descripcion]) VALUES (10, N'Pickup Truck', N'Vehículo con cabina para pasajeros y caja de carga abierta en la parte trasera, generalmente de 2 a 5 plazas, Gran capacidad de carga, resistente y adecuada para terrenos difíciles y trabajos pesados, Mayor consumo de combustible, estacionamiento complicado y menor comodidad de marcha cuando lleva poca carga');
INSERT INTO [dbo].[Categorias] ([Id], [Nombre], [Descripcion]) VALUES (11, N'Minivan', N'Vehículo espacioso de carrocería alta, con puertas traseras corredizas y capacidad para 6 a 8 pasajeros, Amplio espacio interior, cómoda para familias y fácil acceso a los asientos, Mayor consumo de combustible que un automóvil compacto, dimensiones grandes y menor maniobrabilidad en espacios reducidos');
INSERT INTO [dbo].[Categorias] ([Id], [Nombre], [Descripcion]) VALUES (12, N'Microbus', N'Vehículo de carrocería alta y espaciosa, diseñado para transportar entre 8 y 20 pasajeros o mercancías, Gran capacidad de transporte, versátil y adecuada para viajes grupales, Mayor consumo de combustible, estacionamiento complicado y menor maniobrabilidad en calles estrechas');
INSERT INTO [dbo].[Categorias] ([Id], [Nombre], [Descripcion]) VALUES (13, N'Coupe', N'Vehículo de diseño deportivo con carrocería baja, generalmente de 2 puertas y capacidad para 2 a 4 pasajeros, Diseño atractivo, buen rendimiento y conducción deportiva, Espacio interior reducido, acceso complicado a los asientos traseros y menor practicidad para uso familiar');
INSERT INTO [dbo].[Categorias] ([Id], [Nombre], [Descripcion]) VALUES (14, N'Deportivo', N'Vehículo diseñado para ofrecer altas prestaciones, aceleración rápida, gran potencia y manejo preciso, Excelente rendimiento, conducción emocionante y gran estabilidad a altas velocidades, Precio elevado, alto consumo de combustible y espacio interior y de carga reducido');
INSERT INTO [dbo].[Categorias] ([Id], [Nombre], [Descripcion]) VALUES (15, N'Off-Road', N'Vehículo diseñado para circular por terrenos difíciles, con tracción en las cuatro ruedas, suspensión elevada y gran distancia al suelo, Excelente capacidad todoterreno, resistente y adecuado para caminos rocosos, lodo y pendientes pronunciadas, Mayor consumo de combustible, conducción menos cómoda en carretera y mantenimiento costoso');
INSERT INTO [dbo].[Categorias] ([Id], [Nombre], [Descripcion]) VALUES (16, N'Crossover', N'Vehículo que combina características de un automóvil y una SUV, con carrocería elevada, diseño compacto y construcción generalmente monocasco, Cómodo, eficiente en consumo de combustible y versátil para la ciudad y viajes, Menor capacidad todoterreno, espacio de carga limitado frente a SUV grandes y capacidad de remolque reducida');
